#include "EmberAnimation.h"
namespace {
const TMap<FString,FVector2D> Ranges={{TEXT("gpuAmount"),{5,100000}},{TEXT("colliderX"),{-10000,10000}},{TEXT("colliderY"),{-10000,10000}},{TEXT("colliderZ"),{-10000,10000}},{TEXT("colliderRadius"),{1,10000}},{TEXT("colliderSizeX"),{1,10000}},{TEXT("colliderSizeY"),{1,10000}},{TEXT("colliderSizeZ"),{1,10000}},{TEXT("windX"),{-1000,1000}},{TEXT("windY"),{-1000,1000}},{TEXT("windZ"),{-1000,1000}},{TEXT("drag"),{0,10}},{TEXT("attraction"),{-1000,1000}},{TEXT("vortexForce"),{-1000,1000}},{TEXT("vortexLift"),{-500,500}},{TEXT("forceX"),{-10000,10000}},{TEXT("forceY"),{-10000,10000}},{TEXT("forceZ"),{-10000,10000}},{TEXT("rotationSpeed"),{-720,720}},{TEXT("collisionHeight"),{-10000,10000}},{TEXT("restitution"),{0,1}},{TEXT("surfaceFriction"),{0,1}},{TEXT("trailLength"),{.1,10}},{TEXT("radiusVariation"),{0,100}},{TEXT("emitScaleX"),{.1,10}},{TEXT("emitScaleY"),{.1,10}},{TEXT("emitScaleZ"),{.1,10}},{TEXT("spinVariation"),{0,100}},{TEXT("directionRandom"),{0,180}},{TEXT("spriteRotationRandom"),{0,180}},{TEXT("velocityYaw"),{-180,180}},{TEXT("velocityPitch"),{-90,90}},{TEXT("ringSpin"),{-360,360}},{TEXT("amount"),{0,200}},{TEXT("size"),{1,30}},{TEXT("opacity"),{0,1}},{TEXT("speed"),{1,100}},{TEXT("spread"),{5,100}},{TEXT("life"),{1,8}},{TEXT("positionX"),{-10000,10000}},{TEXT("positionY"),{-10000,10000}},{TEXT("positionZ"),{-10000,10000}},{TEXT("gravity"),{-100,100}},{TEXT("turbulence"),{0,100}},{TEXT("endSize"),{0,5}},{TEXT("endOpacity"),{0,1}}};
FString Value(const TSharedPtr<FJsonValue>& V){if(V->Type==EJson::Boolean)return V->AsBool()?TEXT("1.0"):TEXT("0.0");if(V->Type==EJson::String){const FLinearColor C=FLinearColor::FromSRGBColor(FColor::FromHex(V->AsString()));return FString::Printf(TEXT("float3(%s,%s,%s)"),*FString::SanitizeFloat(C.R),*FString::SanitizeFloat(C.G),*FString::SanitizeFloat(C.B));}return FString::SanitizeFloat(V->AsNumber());}
}
bool EmberValidateAnimation(const TSharedPtr<FJsonObject>& E,FString& Error){
 if(!E->HasField(TEXT("animation")))return true;const TSharedPtr<FJsonObject>* A=nullptr;const TArray<TSharedPtr<FJsonValue>>* Keys=nullptr;const TArray<TSharedPtr<FJsonValue>>* Events=nullptr;double Duration;
 if(!E->TryGetObjectField(TEXT("animation"),A)||!(*A)->TryGetNumberField(TEXT("duration"),Duration)||!FMath::IsFinite(Duration)||Duration<1||Duration>60||!(*A)->TryGetArrayField(TEXT("keys"),Keys)||Keys->Num()>64||!(*A)->TryGetArrayField(TEXT("events"),Events)||Events->Num()>32){Error=TEXT("Invalid animation timeline.");return false;}
 TSet<FString> Seen;for(const auto& V:*Keys){const auto K=V->AsObject();double Time;FString Property,Transition;if(!K.IsValid()||!K->TryGetNumberField(TEXT("time"),Time)||!FMath::IsFinite(Time)||Time<0||Time>Duration||!K->TryGetStringField(TEXT("property"),Property)||!K->TryGetStringField(TEXT("transition"),Transition)||(Transition!=TEXT("hold")&&Transition!=TEXT("linear"))||!K->HasField(TEXT("value"))){Error=TEXT("Invalid animation keyframe.");return false;}const FString Identity=Property+TEXT(":")+FString::SanitizeFloat(Time);if(Seen.Contains(Identity)){Error=TEXT("Duplicate animation keyframe.");return false;}Seen.Add(Identity);bool Valid=false;if(Property==TEXT("color")){FString Hex;Valid=K->TryGetStringField(TEXT("value"),Hex)&&Hex.Len()==7&&Hex[0]=='#';if(Valid)for(int32 I=1;I<7;I++)Valid&=FChar::IsHexDigit(Hex[I]);}else if(Property==TEXT("emission")){bool Flag;Valid=K->TryGetBoolField(TEXT("value"),Flag)&&Transition==TEXT("hold");}else if(const FVector2D* Range=Ranges.Find(Property)){double Number;Valid=K->TryGetNumberField(TEXT("value"),Number)&&FMath::IsFinite(Number)&&Number>=Range->X&&Number<=Range->Y;}if(!Valid){Error=TEXT("Invalid animated property value.");return false;}}
 for(const auto& V:*Events){const auto Event=V->AsObject();double Time;FString Type;if(!Event.IsValid()||!Event->TryGetNumberField(TEXT("time"),Time)||!FMath::IsFinite(Time)||Time<0||Time>Duration||!Event->TryGetStringField(TEXT("type"),Type)||(Type!=TEXT("burst")&&Type!=TEXT("clear"))){Error=TEXT("Invalid particle event.");return false;}bool Keep;if(Event->HasField(TEXT("keepAnimation"))&&!Event->TryGetBoolField(TEXT("keepAnimation"),Keep)){Error=TEXT("Invalid burst animation option");return false;}if(Type==TEXT("burst")){double Count;if(!Event->TryGetNumberField(TEXT("count"),Count)||!FMath::IsFinite(Count)||Count<1||Count>2000||Count!=FMath::FloorToDouble(Count)){Error=TEXT("Invalid burst count.");return false;}}}return true;
}
FString EmberAnimatedValue(const TSharedPtr<FJsonObject>& E,const FString& Property,const FString& Base){
 const TSharedPtr<FJsonObject>* A=nullptr;if(!E->TryGetObjectField(TEXT("animation"),A))return Base;TArray<TSharedPtr<FJsonObject>> Keys;for(const auto& V:(*A)->GetArrayField(TEXT("keys"))){const auto K=V->AsObject();if(K->GetStringField(TEXT("property"))==Property)Keys.Add(K);}Keys.Sort([](const TSharedPtr<FJsonObject>& L,const TSharedPtr<FJsonObject>& R){return L->GetNumberField(TEXT("time"))<R->GetNumberField(TEXT("time"));});FString Result=Base;double Previous=0;for(const auto& K:Keys){const double Time=K->GetNumberField(TEXT("time"));const FString Weight=K->GetStringField(TEXT("transition"))==TEXT("linear")&&Time>Previous?FString::Printf(TEXT("saturate((animationTime-%s)/%s)"),*FString::SanitizeFloat(Previous),*FString::SanitizeFloat(Time-Previous)):FString::Printf(TEXT("step(%s,animationTime)"),*FString::SanitizeFloat(Time));Result=FString::Printf(TEXT("lerp(%s,%s,%s)"),*Result,*Value(K->Values[TEXT("value")]),*Weight);Previous=Time;}return Result;
}
